const SOURCE:&str="module representation_cache_maintenance;\nenum Error{Failed,}\nstate Z:Table<u64,Bool> = Table.empty();\nstate Rows:Table<u64,u64> = Table.empty();\nevent seen:u64;\nchange put(key:u64,value:u64)->Result<Unit,Error> writes(Rows) emits(seen){\n if Rows.contains(key){Rows.replace(key,value);}else{Rows.insert(key,value);}\n emit seen(value);return Ok(());\n}\nchange erase(key:u64,fail:Bool)->Result<Unit,Error> writes(Rows) emits(seen){\n Rows.remove(key); Rows.remove(key);\n emit seen(key);\n if fail{return Err(Error.Failed);}return Ok(());\n}\nquery zero()->Option<u64> reads(Rows){return Rows.get(0);}\nquery get(key:u64)->Option<u64> reads(Rows){return Rows.get(key);}\nchange flag(key:u64,value:Bool)->Result<Unit,Error> writes(Z) emits(seen){\n if Z.contains(key){Z.replace(key,value);}else{Z.insert(key,value);}\n emit seen(key);return Ok(());\n}\nquery flagged(key:u64)->Option<Bool> reads(Z){return Z.get(key);}\n";
const DIRECTORY:&str="/Users/james/Documents/ChatGPT/3d-modelling/research/ink-optimisation-2026-10-10/ink-lang/build/compact-query-native";
const TIMED:bool=false;
const COMPOSED:bool=true;
const LIBRARY_PROFILE:&str="debug";
use std::{hint::black_box, time::Instant};
use verified_language::{core::CheckedModule, definition::CheckedDefinition, logic::{Context,Term}, representation::{self,CheckedRepresentation}, stateful::Runtime, syntax::parse};
use ink_runtime::representation::{Executor,Reference,Session};
use serde_json::{json,Value};
#[derive(Clone,Copy)]
struct Unfused;
impl Executor for Unfused {
    fn execute(&self,d:&CheckedDefinition,c:&Context,f:&str,a:Vec<Term>)->ink_core::LangResult<Term>{Native.execute(d,c,f,a)}
}
fn parity<E:Executor>(checked:CheckedRepresentation,module:&CheckedModule,executor:E){
    let mut session=Session::new(checked.clone(),executor).unwrap();
    let mut baseline=Runtime::new(module.program().clone()).unwrap();
    for i in 0..60u64 {
        let (action,args)=match i%10 {
            0=>("put",json!([0,i])),
            1=>("zero",json!([])),
            2=>("flag",json!([i%3,i%2==0])),
            3=>("flagged",json!([i%3])),
            4=>("erase",json!([0,true])),
            5=>("zero",json!([])),
            6=>("put",json!([i+1,i])),
            7=>("get",json!([i+1])),
            8=>("erase",json!([0,false])),
            _=>("zero",json!([])),
        };
        assert_eq!(session.invoke_json(action,&args).unwrap(),baseline.invoke_json(action,&args).unwrap().json());
        assert_eq!(session.checkpoint().unwrap(),baseline.checkpoint_portable().unwrap());
    }
}
fn measure_pair<A:Executor,B:Executor>(old:CheckedRepresentation,new:CheckedRepresentation,bytes:&[u8],before_executor:A,after_executor:B,action:&str,args:&Value)->(Value,Value){
    let mut before=Session::restore(old,bytes,before_executor).unwrap();
    let mut after=Session::restore(new,bytes,after_executor).unwrap();
    fn sample<E:Executor>(session:&mut Session<E>,action:&str,args:&Value,calls:u64)->u64{
        let start=Instant::now();
        for _ in 0..calls {black_box(session.invoke_json(action,black_box(args)).unwrap());session.acknowledge_through(u64::MAX,u64::MAX);}
        start.elapsed().as_nanos() as u64/calls
    }
    sample(&mut before,action,args,32);sample(&mut after,action,args,32);
    let mut a=vec![];let mut b=vec![];
    for round in 0..9 {
        if round%2==0 {a.push(sample(&mut before,action,args,512));b.push(sample(&mut after,action,args,512));}
        else {b.push(sample(&mut after,action,args,512));a.push(sample(&mut before,action,args,512));}
    }
    let report=|samples:Vec<u64>|{let mut sorted=samples.clone();sorted.sort();json!({"samples_ns":samples,"median_ns":sorted[4]})};
    (report(a),report(b))
}
fn main(){
    let module=CheckedModule::from_source(parse(SOURCE).unwrap()).unwrap();
    let load=|label:&str,index:usize|{
        let p:Value=serde_json::from_slice(&std::fs::read(format!("{DIRECTORY}/{label}.json")).unwrap()).unwrap();
        representation::check(&module,&serde_json::from_value(p["requests"][index].clone()).unwrap()).unwrap()
    };
    let old=load("refresh",1);let new=load("preserve",1);
    parity(old.clone(),&module,Native);parity(new.clone(),&module,Native);
    parity(new.clone(),&module,Unfused);parity(new.clone(),&module,Reference);
    let direct=load("preserve",0);
    parity(direct.clone(),&module,Native);parity(direct.clone(),&module,Unfused);parity(direct,&module,Reference);
    // Restores and transaction-boundary migration preserve the source snapshot.
    let mut base=Runtime::new(module.program().clone()).unwrap();
    base.invoke_json("put",&json!([0,99])).unwrap();
    let bytes=base.checkpoint_portable().unwrap();
    let mut migrated=Session::restore(old.clone(),&bytes,Native).unwrap();
    migrated.migrate(new.clone()).unwrap();assert_eq!(migrated.checkpoint().unwrap(),bytes);
    assert_eq!(migrated.invoke_json("zero",&json!([])).unwrap(),base.invoke_json("zero",&json!([])).unwrap().json());
    migrated.migrate(old.clone()).unwrap();assert_eq!(migrated.checkpoint().unwrap(),base.checkpoint_portable().unwrap());
    let layout=ink_core::snapshot::layout(module.program()).unwrap();
    let mut logical=ink_core::snapshot_wire::decode(&layout,&bytes,Default::default()).unwrap();logical.version=u64::MAX;
    let exhausted=ink_core::snapshot_wire::encode(&layout,&logical,Default::default()).unwrap();
    let mut session=Session::restore(new.clone(),&exhausted,Native).unwrap();
    let mut base=Runtime::restore_portable(module.program().clone(),&exhausted).unwrap();
    for (action,args) in [("put",json!([0,3])),("flag",json!([0,true])),("erase",json!([0,false]))]{
        assert!(base.invoke_json(action,&args).is_err());assert!(session.invoke_json(action,&args).is_err());
        assert_eq!(session.checkpoint().unwrap(),exhausted);
    }
    assert_eq!(session.invoke_json("erase",&json!([0,true])).unwrap(),base.invoke_json("erase",&json!([0,true])).unwrap().json());
    assert_eq!(session.checkpoint().unwrap(),exhausted);
    for (action,args) in [("zero",json!([])),("get",json!([0])),("flagged",json!([0]))]{
        assert_eq!(session.invoke_json(action,&args).unwrap(),base.invoke_json(action,&args).unwrap().json());
        assert_eq!(session.checkpoint().unwrap(),exhausted);
    }
    if !TIMED{return;}
    let mut rows=vec![];
    for count in [8,24,48]{
        let mut baseline=Runtime::new(module.program().clone()).unwrap();
        for key in 1..=count {baseline.invoke_json("put",&json!([key,key*2])).unwrap();}
        baseline.invoke_json("flag",&json!([0,true])).unwrap();
        baseline.acknowledge_through(u64::MAX,u64::MAX);
        let bytes=baseline.checkpoint_portable().unwrap();
        for (action,args) in [("zero",json!([])),("get",json!([count])),("flagged",json!([0])),("erase",json!([count,true])),("put",json!([count,77]))]{
            let mut a=Session::restore(old.clone(),&bytes,Native).unwrap();
            let mut b=Session::restore(new.clone(),&bytes,Native).unwrap();
            for _ in 0..4 {let expected=baseline.invoke_json(action,&args).unwrap().json();assert_eq!(a.invoke_json(action,&args).unwrap(),expected);assert_eq!(b.invoke_json(action,&args).unwrap(),expected);assert_eq!(a.checkpoint().unwrap(),baseline.checkpoint_portable().unwrap());assert_eq!(b.checkpoint().unwrap(),a.checkpoint().unwrap());}
            baseline=Runtime::restore_portable(module.program().clone(),&bytes).unwrap();
            // Alternate candidate order in every round to reduce frequency/order bias.
            let (before,after)=measure_pair(old.clone(),new.clone(),&bytes,Native,Native,action,&args);
            let (fallback_before,fallback_after)=measure_pair(old.clone(),new.clone(),&bytes,Unfused,Unfused,action,&args);
            rows.push(json!({"rows":count,"action":action,"before":before,"after":after,"fallback_before":fallback_before,"fallback_after":fallback_after}));
        }
    }
    println!("{}",json!({"schema":1,"composed_action_replacement":COMPOSED,"kind":"DB-only compact query transport; complete Session::invoke_json calls with acknowledgement","source":module.identity().unwrap(),"old_representation":old.request().representation,"new_representation":new.request().representation,"library_profile":LIBRARY_PROFILE,"rounds":9,"order":"alternating candidate order per round","calls_per_round":512,"measurements":rows}));
}
